 exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,\n  jsonb_array_elements(r->'segments') s,jsonb_array_elements(s->'includedLocations') location\n  group by r->>'loan_id',location->>'locationId' having count(distinct r->>'coverer_slot_id')>1) then\n  raise exception 'paired or grouped locations split between lunch helpers'; end if;\n for intent in select value from jsonb_array_elements(p_document->'notification_intents') loop\n  perform public.static_weekly_assert_exact_object(intent,\n   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],\n   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],'lunch notification intent');\n  if coalesce(intent->>'notification_key','') !~ '^[0-9a-f]{64}$'\n   or intent->>'delivery_state' is distinct from 'NOT_ENQUEUED' then raise exception 'invalid lunch notification intent'; end if;\n end loop;\n select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',l->>'service_date',h,e,\n  case e when 'start' then l->>'coverage_start' else l->>'coverage_end' end) order by l->>'loan_id',h,e),'[]') into expected\n from jsonb_array_elements(p_document->'loans') l cross join lateral jsonb_array_elements_text(l->'helper_slot_ids') h\n cross join unnest(array['start','end']) e\n where exists(select 1 from jsonb_array_elements(projection_availability) a\n  where a->>'slotId'=h and a->>'serviceDate'=l->>'service_date' and nullif(a->>'incumbentPersonId','') is not null);\n select coalesce(jsonb_agg(jsonb_build_array(n->>'loan_id',n->>'service_date',n->>'coverer_slot_id',n->>'event',n->>'scheduled_time')\n  order by n->>'loan_id',n->>'coverer_slot_id',n->>'event'),'[]') into actual\n from jsonb_array_elements(p_document->'notification_intents') n;\n if actual is distinct from expected then raise exception 'lunch start/end intents must exactly cover every helper'; end if;\n if exists(select 1 from jsonb_array_elements(p_document->'loans') a join jsonb_array_elements(p_document->'loans') b\n  on a->>'loan_id'<b->>'loan_id' and a->'service_date'=b->'service_date' and a->'helper_slot_ids'=b->'helper_slot_ids'\n  and a->>'coverage_start'<b->>'coverage_end' and b->>'coverage_start'<a->>'coverage_end') then raise exception 'Manual native helper appointments overlap';end if;\n perform public.static_weekly_manual_assert_lunch_lineage(p_envelope,p_document,p_publication,p_week);\nend $function$\n","owner":"postgres","acl":"{postgres=X/postgres}","security":false,"config":["search_path=pg_catalog, public"],"recovery":[],"roots":[],"new":false},{"identity":"public.static_weekly_v8_vacate_roster_slot(uuid,uuid,uuid,date,text,bigint,uuid,text)","beforeSha256":"2cc4429ca14b254253c6e0d7f24b799be493d35a84821f11fc7f54f87c782ce0","afterSha256":"43364601b883b367191730f993a67f067c584992973b66972dd20a2312562c20","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_v8_vacate_roster_slot(p_source_id uuid, p_slot_id uuid, p_employee_id uuid, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare\n  v_actor jsonb;v_prior public.weekly_schedule_command_receipts%rowtype;\n  v_source public.static_weekly_authority_source_documents%rowtype;\n  v_incumbent public.v_weekly_roster_slot_incumbency_ranges%rowtype;\n  v_employee public.employees%rowtype;v_slot jsonb;v_request jsonb;v_request_digest text;\n  v_content_digest text;v_revision bigint;v_command uuid:=gen_random_uuid();v_response jsonb;v_status jsonb;\n  v_original_publication uuid;\nbegin\n  perform public.static_weekly_v3_assert_control_plane();\n  perform public.custodial_assert_manager(p_manager_id);\n  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);\n  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,\n    v_actor->>'manager_name',p_idempotency_key,'vacate_roster_slot');\n  if p_source_id is null or p_slot_id is null or p_employee_id is null or p_effective_start is null\n    or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500\n    or p_reason~'[\\x00-\\x1f\\x7f]' then\n    raise exception using errcode='23514',message='vacancy requires source, position, exact former employee, effective date and bounded reason';\n  end if;\n  v_request:=jsonb_build_object('operation','vacate_roster_slot','source_id',p_source_id,'slot_id',p_slot_id,\n    'employee_id',p_employee_id,'effective_start',p_effective_start,'reason',p_reason,\n    'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);\n  v_request_digest:=public.static_weekly_digest_jsonb(v_request);\n  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));\n  select * into v_prior from public.weekly_schedule_command_receipts\n    where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;\n  if found then\n    if v_prior.request_digest<>v_request_digest then\n      raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs';\n    end if;\n    perform public.static_weekly_v8_assert_vacancy_receipt(v_prior.command_id,'vacate_roster_slot');\n    return v_prior.response_json;\n  end if;\n  -- Immediate turnover only. Do not deactivate someone today for a future vacancy.\n  if p_effective_start<>public.sch_service_date(statement_timestamp()) then\n    raise exception using errcode='23514',message='vacancy effective date must be the current service date; past or future turnover is not supported';\n  end if;\n  select * into v_source from public.static_weekly_authority_source_documents\n    where source_id=p_source_id and active and retired_at is null for share;\n  if not found then raise exception using errcode='23514',message='vacancy requires an active registered source'; end if;\n  select value into v_slot from jsonb_array_elements(v_source.canonical_source->'slots')\n    where value->>'id'=p_slot_id::text;\n  if v_slot is null\n    or not coalesce((v_source.canonical_source#>'{version,vacancyCapableSlotIds}') ? p_slot_id::text,false)\n     then\n    raise exception using errcode='23514',message='registered source must declare this stable position vacancy-capable';\n  end if;\n  select * into v_incumbent from public.v_weekly_roster_slot_incumbency_ranges\n    where slot_id=p_slot_id and effective_start<p_effective_start\n      and (effective_end is null or p_effective_start<effective_end);\n  if not found or v_incumbent.person_id<>p_employee_id then\n    raise exception using errcode='23514',message='vacancy requires the exact effective predecessor incumbent';\n  end if;\n  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges\n      where slot_id=p_slot_id and effective_start>=p_effective_start) then\n    raise exception using errcode='23514',message='future incumbency already occupies this position';\n  end if;\n  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges\n      where person_id=p_employee_id and slot_id<>p_slot_id\n        and (effective_end is null or p_effective_start<effective_end)) then\n    raise exception using errcode='23514',message='former employee also has another current or future position';\n  end if;\n  select * into v_employee from public.employees where id=p_employee_id for update;\n  if not found then raise exception using errcode='23514',message='predecessor employee identity is missing'; end if;\n  \n  -- Bind the original completion shape under the same authority lock and\n  -- effective-week selector as the manager snapshot. Absence of a later\n  -- projection receipt must never be interpreted as an unpublished action.\n  select publication_id into v_original_publication from public.weekly_schedule_publications\n    where version_id=public.static_weekly_effective_version(\n      p_effective_start-(extract(isodow from p_effective_start)::integer-1));\n  -- The authenticated accepted-pattern compound transaction owns its new\n  -- publication and paired lunch. Its private, immutable, exact seven-person\n  -- packet is not the standalone old-publication vacancy workflow. A caller\n  -- cannot select this mode through an argument or session setting.\n  if exists(select 1 from custodial_coverall.activation_operations operation\n    join custodial_coverall.activation_packets packet using(packet_id)\n    where operation.owner_xid=pg_current_xact_id()\n     and operation.manager_id=p_manager_id and packet.manager_id=p_manager_id\n     and packet.expected_revision=p_expected_revision and packet.service_date=p_effective_start\n     and packet.source_id<>p_source_id\n     and packet.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY'\n     and packet.approval_json->>'artifactSha256'='22d067bd595e2450bb32cd36903df94628eb6df055a44f992b3aba9f242bbee7'\n     and packet.source_json#>>'{version,lunchCoveragePolicy,sourceDigest}'='fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58'\n     and packet.approval_json#>>'{vacancy,employeeId}'=p_employee_id::text\n     and packet.approval_json#>>'{vacancy,slotId}'=p_slot_id::text\n     and packet.approval_json#>>'{vacancy,effectiveDate}'=p_effective_start::text\n     and packet.approval_json#>>'{vacancy,expectedRevision}'=p_expected_revision::text\n     and packet.approval_json#>>'{vacancy,expectedPostRevision}'=(p_expected_revision+1)::text) then\n   -- This remains a truthful mutation-only subreceipt. The outer operation\n   -- must verify its actual normal source/publication/lunch before commit;\n   -- any failure rolls this vacancy and protected separation back as well.\n   v_original_publication:=null;\n  end if;\n  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');\n  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'vacate_roster_slot',\n    p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);\n  insert into public.weekly_roster_slot_staffing_states(\n    slot_id,employee_id,staffing_state,effective_start,authority_revision,\n    actor_manager_id,actor_manager_name_snapshot,reason,content_digest)\n  values(p_slot_id,null,'vacant_unfilled',p_effective_start,v_revision,\n    p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);\n  insert into public.weekly_roster_slot_incumbency_closures(\n    closed_incumbency_id,replacement_incumbency_id,closed_at_effective_date,authority_revision,\n    actor_manager_id,actor_manager_name_snapshot,content_digest)\n  values(v_incumbent.incumbency_id,null,p_effective_start,v_revision,\n    p_manager_id,v_actor->>'manager_name',v_content_digest);\n  v_status:=public.custodial_v12_inactivate_preserving_work(p_employee_id,p_slot_id,p_manager_id,p_reason,v_revision,v_command,p_effective_start);\n  v_response:=public.static_weekly_response_json('vacate_roster_slot',v_revision,v_content_digest,\n    v_request_digest,jsonb_build_object('slot_id',p_slot_id,'former_employee_id',p_employee_id,\n      'replacement_employee_id',null,'effective_start',p_effective_start,'source_id',p_source_id,\n      'source_digest',v_source.source_digest,'employee_status',v_status,'history_preserved',true,\n      'completion_mode',case when v_original_publication is null then 'mutation_only' else 'projection_required' end,\n      'original_publication_id',v_original_publication));\n  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,\n    actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,\n    request_canonical_json,response_json,response_digest,content_digest)\n  values(v_command,p_manager_id,v_actor->>'manager_name','vacate_roster_slot',p_idempotency_key,\n    p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);\n  return v_response;\nend\n$function$\n","owner":"postgres","acl":"{postgres=X/postgres,static_weekly_control_plane=X/postgres}","security":true,"config":["search_path=pg_catalog, public"],"recovery":[{"kind":"function","sha256":"2cc4429ca14b254253c6e0d7f24b799be493d35a84821f11fc7f54f87c782ce0","identity":"public.static_weekly_v8_vacate_roster_slot(uuid,uuid,uuid,date,text,bigint,uuid,text)"},{"kind":"grant","sha256":"aaf5aa4150d9c201ef0995a2608389371f697ccbb78f71f99da01c1368e517c6","identity":"public.static_weekly_v8_vacate_roster_slot(uuid,uuid,uuid,date,text,bigint,uuid,text)"}],"roots":[],"new":false},{"identity":"public.static_weekly_assert_manual_roster_transition(jsonb,jsonb,jsonb)","beforeSha256":"cd80bbe94415c1485c3f2acb0a12a62484575a51c0c69da9e8e45f83fd66ad60","afterSha256":"d2f88ac9a55e05d9eab8deaf01df001fcc7fcde00737a220b85a155b9018b26e","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_assert_manual_roster_transition(p_transition jsonb, p_snapshot jsonb, p_config jsonb)\n RETURNS void\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare target jsonb;slot jsonb;person jsonb;current_rows jsonb;current_person jsonb;change jsonb;\n at date;expected_transfers integer:=0;expected_unchanged integer:=0;matches integer;\nbegin\n at:=(p_snapshot->>'serviceDate')::date;\n if p_transition->>'schema' is distinct from 'custodial.approved-manual-roster-transition.v1'\n  or p_transition->>'status' is distinct from 'PREPARED_NOT_ADMITTED'\n  or p_transition->>'serviceDate' is distinct from at::text\n  or p_transition->'expectedRevision' is distinct from p_snapshot->'authorityRevision'\n  or p_transition->'parentPublication' is distinct from p_snapshot->'parentPublication'\n  or p_transition->>'readbackDigest' is distinct from public.static_weekly_digest_jsonb(p_snapshot)\n  or p_transition->>'transitionDigest' is distinct from public.static_weekly_digest_jsonb(p_transition-'transitionDigest')\n  or not coalesce((p_transition->>'manualDataDigest'='eeff371f1510c6e4a079bde3ba17136dc10f64b100c7562d9b139fd14805a1c8'\n    and (select count(*) from jsonb_each(p_config->'slots') s where s.value->'vacancy'='false'::jsonb)=8)\n   or (p_transition->>'manualDataDigest'='fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58' and p_config->>'approvedManualDataDigest'='fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58'\n    and (select count(*) from jsonb_each(p_config->'slots') s where s.value->'vacancy'='false'::jsonb)=7),false)\n  or p_transition->'liveSlotCount' is distinct from to_jsonb(jsonb_array_length(p_snapshot->'rosterSlots'))\n  or jsonb_array_length(p_snapshot->'employees')<>8 then\n  raise exception using errcode='40001',message='manual activation roster, source, date, parent or revision changed';end if;\n for target in select value from jsonb_each(p_config->'slots') where value->'vacancy'='false'::jsonb loop\n  select value into strict person from jsonb_array_elements(p_snapshot->'employees') where value->>'employeeId'=target->>'personId';\n  select value into strict slot from jsonb_array_elements(p_snapshot->'rosterSlots') where value->>'slotId'=target->>'slotId';\n  if person->'active' is distinct from 'true'::jsonb or person->'hasMessenger' is distinct from 'true'::jsonb\n   or person->>'displayName' is distinct from target->>'name' or coalesce(person->>'employeeCode','')!~'^EMP[0-9]+$'\n   or exists(select 1 from jsonb_array_elements(p_snapshot->'rosterSlots') s\n    cross join lateral jsonb_array_elements(s->'incumbencies') r where s->>'slotId'<>target->>'slotId'\n     and r->>'personId'=target->>'personId' and (r->>'effectiveEnd' is null or at<(r->>'effectiveEnd')::date)) then\n   raise exception using errcode='23514',message='manual activation requires the exact existing active employee, Messenger and stable position';end if;\n  select coalesce(jsonb_agg(r),'[]'::jsonb) into current_rows from jsonb_array_elements(slot->'incumbencies') r\n   where (r->>'effectiveStart')::date<=at and (r->>'effectiveEnd' is null or at<(r->>'effectiveEnd')::date);\n  if jsonb_array_length(current_rows)>1 then raise exception 'overlapping current roster authority';end if;\n  current_person:=current_rows->0;\n  if current_person->>'personId'=target->>'personId' then\n   expected_unchanged:=expected_unchanged+1;\n   select count(*) into matches from jsonb_array_elements(p_transition->'unchanged') r\n    where r=jsonb_build_object('slotId',target->>'slotId','employeeId',target->>'personId','incumbencyId',current_person->>'incumbencyId');\n   if matches<>1 or exists(select 1 from jsonb_array_elements(slot->'incumbencies') r where (r->>'effectiveStart')::date>at) then\n    raise exception 'unchanged manual roster identity changed';end if;\n  else\n   expected_transfers:=expected_transfers+1;\n   if exists(select 1 from jsonb_array_elements(slot->'incumbencies') r where (r->>'effectiveStart')::date>=at) then\n    raise exception 'manual activation cannot replace a current-day or future incumbency';end if;\n   select value into strict change from jsonb_array_elements(p_transition->'transfers') r\n    where r->>'slotId'=target->>'slotId' and r->>'employeeId'=target->>'personId';\n   if change->>'employeeName' is distinct from person->>'displayName' or change->>'slotLabel' is distinct from slot->>'label'\n    or change->>'effectiveStart' is distinct from at::text\n    or change->>'expectedLiveRangeDigest' is distinct from public.static_weekly_digest_jsonb(slot)\n    or change->'newEmployeeCreated' is distinct from 'false'::jsonb or change->'messengerPrincipalCreated' is distinct from 'false'::jsonb\n    or change->'phoneAssignment' is distinct from 'null'::jsonb then raise exception 'manual roster transfer binding changed';end if;\n   if current_person is null then\n    if change->>'operation' is distinct from 'ASSIGN_EXISTING_EMPLOYEE_TO_EMPTY_SLOT' or change->'closure' is distinct from 'null'::jsonb then\n     raise exception 'empty manual position cannot invent former history';end if;\n   elsif change->>'operation' is distinct from 'REASSIGN_EXISTING_EMPLOYEE'\n    or change->'closure' is distinct from jsonb_build_object('incumbencyId',current_person->>'incumbencyId',\n     'personId',current_person->>'personId','displayName',current_person->>'displayName','effectiveStart',current_person->>'effectiveStart',\n     'previousEffectiveEnd',current_person->'effectiveEnd','closeAt',at::text) then\n    raise exception 'manual transfer requires the exact append-only predecessor closure';\n   end if;\n  end if;\n end loop;\n if jsonb_array_length(p_transition->'transfers')<>expected_transfers or jsonb_array_length(p_transition->'unchanged')<>expected_unchanged then\n  raise exception 'manual transition has extra or missing roster operations';end if;\nend $function$\n","owner":"postgres","acl":"{postgres=X/postgres}","security":false,"config":["search_path=pg_catalog, public"],"recovery":[{"kind":"function","sha256":"cd80bbe94415c1485c3f2acb0a12a62484575a51c0c69da9e8e45f83fd66ad60","identity":"static_weekly_assert_manual_roster_transition(jsonb,jsonb,jsonb)"},{"kind":"grant","sha256":"5f63380fb0e32dc45579988f2618c2d0525932ebad878de2297d446b7661c8fe","identity":"static_weekly_assert_manual_roster_transition(jsonb,jsonb,jsonb)"}],"roots":[{"purpose":"approved current-day activation; seven immutable normal days","object_kind":"function","object_identity":"static_weekly_assert_manual_roster_transition(jsonb,jsonb,jsonb)"},{"purpose":"approved current-day activation; seven immutable normal days","object_kind":"grant","object_identity":"static_weekly_assert_manual_roster_transition(jsonb,jsonb,jsonb)"}],"new":false},{"identity":"public.static_weekly_coverall_assert_activation_data(jsonb,jsonb)","beforeSha256":"5ab5828256bb62bd163288297dff9d00c171e9de19e8b5bec62fdb19a3093fde","afterSha256":"dc7bac7c1230bd9b4fa56a61a375f1b7143ae8cbfba22997c80d67cd02527f0f","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_coverall_assert_activation_data(p_data jsonb, p_snapshot jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE source jsonb:=p_data->'source';transition jsonb:=p_data->'transition';cp jsonb:=p_data->'capacityTransition';\n oldsource jsonb;oldslot jsonb;newslot jsonb;mapping jsonb;expected jsonb;actual jsonb;ids text[];row jsonb;at date;end_date date;\nBEGIN\n IF p_data IS NULL OR pg_column_size(p_data)>33554432 THEN RAISE EXCEPTION 'Bounded current-date activation DATA required';END IF;\n IF p_data->>'schema'='custodial.accepted-seven-pattern-update-data.v1' THEN\n  PERFORM custodial_coverall.assert_accepted_seven_update_data(p_data,p_snapshot);RETURN;\n END IF;\n IF p_data->>'schema' IS DISTINCT FROM 'custodial.approved-manual-coverall-activation-data.v1'\n  OR jsonb_array_length(p_snapshot->'rosterSlots')<>22 OR p_data->'currentPositions'<>'22'::jsonb\n  OR p_data->'additionalCapacityPositions'<>'8'::jsonb OR p_data->'prospectivePositions'<>'30'::jsonb OR p_data->'newEmployees'<>'0'::jsonb\n  OR p_data->'weeklyBaselineChanged' IS DISTINCT FROM 'false'::jsonb OR p_data->'registered' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'published' IS DISTINCT FROM 'false'::jsonb OR p_data->'productionWritten' IS DISTINCT FROM 'false'::jsonb\n THEN RAISE EXCEPTION 'Exact original22 plus eight NEW nonemployee capacity DATA required';END IF;\n at:=(p_snapshot->>'serviceDate')::date;end_date:=at+6;\n IF source->>'serviceDate'<>at::text OR source#>>'{version,effectiveStart}'<>at::text\n  OR p_data->>'serviceDate'<>at::text OR p_data->>'windowEnd'<>end_date::text\n  OR source->>'serviceDate'<>p_data#>>'{capacityTransition,serviceDate}'\n  OR p_data->>'sourceDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(source)\n  OR source->'exceptions' IS DISTINCT FROM '[]'::jsonb\n THEN RAISE EXCEPTION 'Native capacity activation uses current service date and exact immutable Source';END IF;\n PERFORM public.static_weekly_assert_manual_roster_transition(transition,p_snapshot,p_data->'ownerConfig');\n oldsource:=transition->'projectedSourceDraft';\n IF cp->>'capacityTransitionDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(cp-'capacityTransitionDigest')\n  OR cp->>'rosterReadbackDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_snapshot)\n  OR cp->>'normalRosterTransitionDigest' IS DISTINCT FROM transition->>'transitionDigest'\n  OR jsonb_array_length(cp->'selection')<>8 OR jsonb_array_length(source->'slots')<>17\n  OR jsonb_array_length(source#>'{version,assignments}') IS DISTINCT FROM (CASE p_data#>>'{ownerConfig,approvedManualDataDigest}' WHEN 'eeff371f1510c6e4a079bde3ba17136dc10f64b100c7562d9b139fd14805a1c8' THEN 346 WHEN '85ad93db39597cffc033992ec74d5eea98612ce9a8388a9e93f5566f4e38bc4c' THEN 327 ELSE -1 END)\n  OR source#>>'{version,lunchCoveragePolicy,sourceDigest}' IS DISTINCT FROM p_data#>>'{ownerConfig,approvedManualDataDigest}'\n  OR transition->>'manualDataDigest' IS DISTINCT FROM p_data#>>'{ownerConfig,approvedManualDataDigest}'\n  OR (SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(source#>'{version,assignments}') x)\n   IS DISTINCT FROM(SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(oldsource#>'{version,assignments}') x)\n  OR source#>'{version,lunchCoveragePolicy}' IS DISTINCT FROM oldsource#>'{version,lunchCoveragePolicy}'\n  OR source->'proximity' IS DISTINCT FROM oldsource->'proximity'\n  OR (source->'version')-ARRAY['id','publicationId','status','effectiveStart','namedAbsentSlotIds','vacancyCapableSlotIds','vacantSlotIds','slotAvailability','assignments']\n   IS DISTINCT FROM (oldsource->'version')-ARRAY['id','publicationId','status','effectiveStart','namedAbsentSlotIds','vacancyCapableSlotIds','vacantSlotIds','slotAvailability','assignments']\n  OR (SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(source#>'{version,slotAvailability}') x)\n   IS DISTINCT FROM(SELECT jsonb_agg(x ORDER BY x::text) FROM jsonb_array_elements(oldsource#>'{version,slotAvailability}') x)\n THEN RAISE EXCEPTION 'Shared mapper/roster/normal geometry binding differs';END IF;\n SELECT array_agg(x->>'new_capacity_id') INTO ids FROM jsonb_array_elements(cp->'selection') x;\n IF (SELECT count(DISTINCT x) FROM unnest(ids) x)<>8 OR EXISTS(SELECT 1 FROM public.weekly_roster_slots WHERE slot_id::text=ANY(ids))\n  OR (SELECT count(DISTINCT x->>'capacity_code') FROM jsonb_array_elements(cp->'selection') x)<>8\n THEN RAISE EXCEPTION 'Capacity IDs/codes must be eight unique NEW positions';END IF;\n FOR mapping IN SELECT value FROM jsonb_array_elements(cp->'selection') LOOP\n  SELECT x INTO STRICT oldslot FROM jsonb_array_elements(oldsource->'slots') x WHERE x->'id'=mapping->'legacy_slot_id' AND x->'contractorCapacity'='true'::jsonb;\n  SELECT x INTO STRICT newslot FROM jsonb_array_elements(source->'slots') x WHERE x->'id'=mapping->'new_capacity_id';\n  expected:=jsonb_build_object('id',mapping->'new_capacity_id','capacityId',mapping->'new_capacity_id','label',mapping->'capacity_code',\n   'kind','CONTRACTOR_CAPACITY','contractorCapacity',true,'incumbencies','[]'::jsonb,'contractorAvailability',oldslot->'contractorAvailability');\n  IF newslot IS DISTINCT FROM expected OR EXISTS(SELECT 1 FROM public.static_weekly_contractor_capacity_registrations WHERE capacity_code=mapping->>'capacity_code')\n  THEN RAISE EXCEPTION 'Source-bound typed capacity template/codes require explicit reconciliation';END IF;\n  PERFORM public.static_weekly_capacity_assert_shape(newslot);\n END LOOP;\n FOR oldslot IN SELECT value FROM jsonb_array_elements(oldsource->'slots') WHERE value->'contractorCapacity' IS DISTINCT FROM 'true'::jsonb LOOP\n  SELECT coalesce(jsonb_agg(x ORDER BY n),'[]') INTO actual FROM jsonb_array_elements(oldslot->'incumbencies') WITH ORDINALITY q(x,n)\n   WHERE (x->>'effectiveStart')::date<=end_date AND (x->>'effectiveEnd' IS NULL OR (x->>'effectiveEnd')::date>at);\n  SELECT x INTO STRICT newslot FROM jsonb_array_elements(source->'slots') x WHERE x->'id'=oldslot->'id';\n  IF newslot IS DISTINCT FROM (oldslot||jsonb_build_object('incumbencies',actual)) THEN RAISE EXCEPTION 'Ordinary employee or history facts changed';END IF;\n END LOOP;\n IF p_data#>'{feasibility,candidateSource}' IS DISTINCT FROM source OR p_data#>'{template,source}' IS DISTINCT FROM source\n  OR p_data#>'{feasibility,solverInvoked}' IS DISTINCT FROM 'false'::jsonb OR p_data#>'{feasibility,mapping,unchanged}' IS DISTINCT FROM 'true'::jsonb\n  OR jsonb_array_length(p_data#>'{feasibility,initialBaseline,projection,assignments}') IS DISTINCT FROM (CASE p_data#>>'{ownerConfig,approvedManualDataDigest}' WHEN 'eeff371f1510c6e4a079bde3ba17136dc10f64b100c7562d9b139fd14805a1c8' THEN 346 WHEN '85ad93db39597cffc033992ec74d5eea98612ce9a8388a9e93f5566f4e38bc4c' THEN 327 ELSE -1 END)\n  OR jsonb_array_length(p_data#>'{feasibility,lunchDocument,loans}')<>40\n THEN RAISE EXCEPTION 'Existing fixed-pattern adapter snapshot, not a new optimizer receipt, required';END IF;\nEND $function$\n","owner":"postgres","acl":"{postgres=X/postgres}","security":true,"config":["search_path=pg_catalog, public"],"recovery":[{"kind":"function","sha256":"5ab5828256bb62bd163288297dff9d00c171e9de19e8b5bec62fdb19a3093fde","identity":"public.static_weekly_coverall_assert_activation_data(jsonb,jsonb)"},{"kind":"grant","sha256":"11be19e4acd029240b86fa0e658529216d26318d2627e86b47bdb8514a89bc73","identity":"public.static_weekly_coverall_assert_activation_data(jsonb,jsonb)"}],"roots":[{"purpose":"exact approved manual shift policy and component count authority","object_kind":"function","object_identity":"public.static_weekly_coverall_assert_activation_data(jsonb,jsonb)"},{"purpose":"exact approved manual shift policy and component count authority","object_kind":"grant","object_identity":"public.static_weekly_coverall_assert_activation_data(jsonb,jsonb)"}],"new":false},{"identity":"public.static_weekly_begin_coverall_activation(uuid,uuid,uuid,bigint,text,uuid,text,text)","beforeSha256":"6fad6b27cc5a4558c385c5ca3533a3f8025708265e8b60bc70bd9a42a8ab130a","afterSha256":"2c54eea1bcb919590632eb3b23a2391edf88f5b70f56f85fdfbe0e6228f41b38","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_begin_coverall_activation(p_manager uuid, p_packet uuid, p_operation uuid, p_revision bigint, p_preview text, p_credential uuid, p_device text, p_access text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE packet record;snapshot jsonb;request jsonb;prior record;slot jsonb;actor jsonb;code text;basis jsonb;result jsonb;employees_before text;\nBEGIN\n PERFORM public.static_weekly_v3_assert_control_plane();actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'write');\n PERFORM public.custodial_begin_application_mutation();PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));\n IF EXISTS(SELECT 1 FROM custodial_coverall.activation_packets packet WHERE packet.packet_id=p_packet\n  AND packet.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY') THEN\n  RETURN custodial_coverall.begin_accepted_seven_update(p_manager,p_packet,p_operation,p_revision,p_preview,p_credential,p_device,p_access);\n END IF;\n request:=jsonb_build_object('managerId',p_manager,'packetId',p_packet,'operationId',p_operation,'expectedRevision',p_revision,'previewDigest',p_preview);\n SELECT o.request_json,r.receipt_json INTO prior FROM custodial_coverall.activation_operations o JOIN custodial_coverall.activation_receipts r USING(operation_id) WHERE o.operation_id=p_operation;\n IF FOUND THEN IF prior.request_json IS DISTINCT FROM request THEN RAISE EXCEPTION 'Original activation identity conflict';END IF;RETURN prior.receipt_json;END IF;\n -- Explicit scalar/source/config fields ONLY: the outer transaction never\n -- retains a13MBfeasibility record while native helpers allocate components.\n SELECT packet_id,source_id,template_id,manager_id,service_date,expected_revision,roster_digest,preview_digest,\n  source_json,source_digest,transition_json,capacity_json,owner_config,template_json,binding_json,approval_json,packet_fingerprint\n INTO STRICT packet FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;\n snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));\n IF p_operation IS NULL OR packet.manager_id<>p_manager OR packet.expected_revision<>p_revision OR p_preview IS DISTINCT FROM (public.static_weekly_read_coverall_activation_basis(p_manager,p_packet,p_revision)->>'previewDigest')\n  OR packet.service_date::text<>snapshot->>'serviceDate' OR p_revision::text<>snapshot->>'authorityRevision'\n  OR packet.roster_digest<>public.static_weekly_digest_jsonb(snapshot)\n THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Current typed activation Source/manager/roster/revision changed';END IF;\n SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(e) ORDER BY e.id)) INTO employees_before FROM public.employees e;\n INSERT INTO custodial_coverall.activation_operations VALUES(p_operation,p_packet,p_manager,pg_current_xact_id(),request);\n INSERT INTO public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)\n VALUES(packet.source_id,packet.source_json,packet.source_digest,'approved-manual-coverall:'||p_operation);\n FOR slot IN SELECT value FROM jsonb_array_elements(packet.source_json->'slots') WHERE value->>'kind'='CONTRACTOR_CAPACITY' LOOP\n  PERFORM public.static_weekly_capacity_assert_shape(slot);code:='STATIC_'||upper(replace(slot->>'id','-',''));\n  INSERT INTO public.weekly_roster_slots(slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest)\n  VALUES((slot->>'id')::uuid,code,slot->>'label',p_manager,actor->>'manager_name',public.static_weekly_digest_jsonb(jsonb_build_object('source_id',packet.source_id,'slot_id',slot->>'id','slot_code',code,'slot_label',slot->>'label')));\n  INSERT INTO public.static_weekly_contractor_capacity_registrations(capacity_slot_id,capacity_code,source_id,source_digest,slot_snapshot,slot_digest,registered_by_manager_id,manager_name_snapshot)\n  VALUES((slot->>'id')::uuid,slot->>'label',packet.source_id,packet.source_digest,slot,public.static_weekly_digest_jsonb(slot),p_manager,actor->>'manager_name');\n END LOOP;\n PERFORM public.static_weekly_v3_source_identity(packet.source_json);\n PERFORM public.static_weekly_coverall_register_template(packet.source_id,packet.template_json,packet.binding_json,packet.owner_config,packet.approval_json);\n INSERT INTO public.static_weekly_manual_activation_packets(packet_id,source_id,template_id,service_date,manager_id,transition_json,feasibility_json,packet_digest)\n SELECT packet_id,source_id,template_id,service_date,manager_id,transition_json,feasibility_json,packet_fingerprint FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;\n basis:=public.static_weekly_coverall_activation_basis(p_manager,p_packet,p_revision);\n result:=public.static_weekly_coverall_activate_source301(p_manager,p_packet,p_revision,basis->>'previewDigest','coverall-source:'||p_operation);\n IF result->>'status'<>'PERSISTED_CURRENT' OR result->>'source_id'<>packet.source_id::text\n  OR (SELECT count(*) FROM public.weekly_roster_slots)<>30\n  OR employees_before IS DISTINCT FROM(SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(e) ORDER BY e.id)) FROM public.employees e)\n  OR EXISTS(SELECT 1 FROM public.weekly_roster_slot_incumbencies WHERE slot_id::text IN(SELECT jsonb_array_elements_text(packet.capacity_json->'newCapacityIds')))\n THEN RAISE EXCEPTION 'Atomic source/registry/roster/normal346/40 publication did not preserve employees and empty nonemployee capacity';END IF;\n RETURN public.static_weekly_coverall_record_activation_begin(p_operation,p_manager,p_credential,p_device,p_access,result);\nEND $function$\n","owner":"postgres","acl":"{postgres=X/postgres,static_weekly_control_plane=X/postgres}","security":true,"config":["search_path=pg_catalog, public"],"recovery":[],"roots":[],"new":false},{"identity":"public.static_weekly_coverall_activation_filtered_roster(uuid)","beforeSha256":"29952de426bb7ca2e2ef747b23be6af25b56251219be44dee501ff7695d7c12a","afterSha256":"8f25876128b3cdb9835ca8d6aa9747e22fe6c25e4b6d80b382dae33bb79db660","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_coverall_activation_filtered_roster(p_packet uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE snapshot jsonb;ids jsonb;slots jsonb;\nBEGIN\n IF NOT EXISTS(SELECT 1 FROM custodial_coverall.activation_operations o WHERE o.packet_id=p_packet AND o.owner_xid=pg_current_xact_id())\n THEN RAISE EXCEPTION 'Only this atomic original activation may exclude its own eight new empty capacity positions from the original22 CAS';END IF;\n IF EXISTS(SELECT 1 FROM custodial_coverall.activation_packets packet WHERE packet.packet_id=p_packet\n  AND packet.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY') THEN\n  snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));\n  IF NOT EXISTS(SELECT 1 FROM custodial_coverall.activation_packets packet WHERE packet.packet_id=p_packet\n   AND packet.approval_json#>>'{vacancy,expectedPostRosterDigest}'=public.static_weekly_digest_jsonb(snapshot)\n   AND packet.approval_json#>'{vacancy,expectedPostSnapshot}'=snapshot)\n  THEN RAISE EXCEPTION 'Actual accepted-update post-vacancy roster differs';END IF;\n  RETURN snapshot;\n END IF;\n SELECT capacity_json->'newCapacityIds' INTO STRICT ids FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;\n snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));\n IF jsonb_array_length(snapshot->'rosterSlots')<>30 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'rosterSlots') s\n  WHERE ids?(s->>'slotId') AND jsonb_array_length(s->'incumbencies')<>0) THEN RAISE EXCEPTION 'Expected22 histories plus eight empty nonemployee positions';END IF;\n SELECT jsonb_agg(s ORDER BY s->>'slotId') INTO slots FROM jsonb_array_elements(snapshot->'rosterSlots') s WHERE NOT ids?(s->>'slotId');\n IF jsonb_array_length(slots)<>22 THEN RAISE EXCEPTION 'Original history slot set differs';END IF;\n RETURN jsonb_set(snapshot,'{rosterSlots}',slots,false);\nEND $function$\n","owner":"postgres","acl":"{postgres=X/postgres}","security":true,"config":["search_path=pg_catalog, public"],"recovery":[],"roots":[],"new":false},{"identity":"public.static_weekly_read_coverall_activation_basis(uuid,uuid,bigint)","beforeSha256":"c2d16af35d6f1c74b68a97882eb6026c48c4a96eab87074201a36fd2da17f19d","afterSha256":"3040b7a417fef0bea34236386fd03fe568138304035baa07808fe65a5bb7d7d4","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_read_coverall_activation_basis(p_manager uuid, p_packet uuid, p_revision bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE packet record;snapshot jsonb;employment jsonb:='[]';vector jsonb;d date;body jsonb;\nBEGIN\n PERFORM public.static_weekly_v3_assert_control_plane();PERFORM public.static_weekly_v3_manager_actor(p_manager);\n PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));\n SELECT packet_id,source_id,template_id,manager_id,service_date,expected_revision,roster_digest,preview_digest,packet_fingerprint,source_digest,approval_json INTO packet\n FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;\n IF NOT FOUND THEN RETURN NULL;END IF;\n snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));\n IF packet.manager_id<>p_manager OR packet.expected_revision<>p_revision OR p_revision::text<>snapshot->>'authorityRevision'\n  OR packet.service_date::text<>snapshot->>'serviceDate' OR packet.roster_digest<>public.static_weekly_digest_jsonb(snapshot)\n THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Original current typed activation packet/manager/date/roster/revision changed';END IF;\n FOR d IN SELECT generate_series(packet.service_date,packet.service_date+6,'1 day')::date LOOP\n  employment:=employment||jsonb_build_array(custodial_employment.native_read(d,p_revision,p_manager));END LOOP;\n SELECT jsonb_agg(jsonb_build_object('serviceDate',day->'serviceDate','employeeId',e->'employeeId','employmentRevision',e->'employmentRevision','requestId',e#>'{command,requestId}') ORDER BY day->>'serviceDate',e->>'employeeId')\n INTO vector FROM jsonb_array_elements(employment) days(day) CROSS JOIN LATERAL jsonb_array_elements(day->'employees') employees(e);\n IF jsonb_array_length(vector)<>14 THEN RAISE EXCEPTION 'Actual fourteen employment bindings required';END IF;\n body:=jsonb_build_object('schema','custodial.approved-manual-coverall-activation-preview-basis.v2','managerId',p_manager,'packetId',p_packet,\n  'sourceId',packet.source_id,'templateId',packet.template_id,'serviceDate',packet.service_date,'windowEnd',packet.service_date+6,'expectedRevision',p_revision,\n  'packetPreviewDigest',packet.preview_digest,'packetFingerprint',packet.packet_fingerprint,'sourceDigest',packet.source_digest,'employmentRevisionVector',vector,\n  'currentPositions',CASE WHEN packet.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY' THEN jsonb_array_length(snapshot->'rosterSlots') ELSE 22 END,'additionalCapacityPositions',CASE WHEN packet.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY' THEN 0 ELSE 8 END,'prospectivePositions',30,'newEmployees',0);\n IF packet.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY' THEN\n  body:=body||jsonb_build_object('operationKind','ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY','manualDataDigest','fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58','acceptedArtifactSha256','22d067bd595e2450bb32cd36903df94628eb6df055a44f992b3aba9f242bbee7');\n END IF;\n RETURN body||jsonb_build_object('previewDigest',public.static_weekly_digest_jsonb(body),'normalPatternSolverInvoked',false,'operationalAdjustmentPending',true,'published',false);\nEND $function$\n","owner":"postgres","acl":"{postgres=X/postgres,static_weekly_control_plane=X/postgres}","security":true,"config":["search_path=pg_catalog, public"],"recovery":[],"roots":[],"new":false},{"identity":"public.static_weekly_read_manual_repeat_basis(uuid,uuid,date,bigint,uuid,text,text)","beforeSha256":"61e67e2c6dc67355d1fd4744520b22634de4e7c8a8a4ec113589ed0dccfdfdc9","afterSha256":"bb08ed96b3986a0cdd2500c2e41a53dcb38f2aabfe0e5e3d73cb9b6559a4294a","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_read_manual_repeat_basis(p_manager uuid, p_publication uuid, p_date date, p_revision bigint, p_credential uuid, p_device text, p_access text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE actor jsonb;v_source_id uuid;v_version_id uuid;origin date;frame date;snapshot text;catalog text;projection jsonb;lunch jsonb;\n entry record;exceptions jsonb;reasons jsonb:='[]';participants jsonb;employment jsonb:='[]';readback jsonb;\n d date;a jsonb;r record;existing uuid;\nBEGIN\n PERFORM public.static_weekly_v3_assert_control_plane();\n actor:=public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'read');\n PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));\n IF p_revision IS NULL OR p_revision NOT BETWEEN 0 AND 9007199254740990 OR p_revision IS DISTINCT FROM\n  (SELECT current_revision FROM public.static_weekly_schedule_control WHERE singleton)\n  OR p_date IS NULL OR NOT isfinite(p_date) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Current recurring date/revision required'; END IF;\n SELECT v.authority_source_id,v.version_id,p.effective_start INTO STRICT v_source_id,v_version_id,origin\n FROM public.weekly_schedule_publications p JOIN public.weekly_schedule_versions v USING(version_id)\n WHERE p.publication_id=p_publication;\n SELECT b.snapshot_digest,b.feasibility#>'{initialBaseline,projection}' AS projection_component,b.feasibility->'lunchDocument' AS lunch_component,c.catalog_entry_digest,\n  c.template_json,c.binding_json,c.owner_config,c.approval_evidence,c.template_id INTO STRICT entry\n FROM public.static_weekly_approved_initial_baselines b JOIN public.static_weekly_approved_template_catalog c USING(template_id)\n JOIN public.static_weekly_authority_source_documents s ON s.source_id=b.source_id\n WHERE b.source_id=v_source_id AND b.effective_start=origin AND s.active AND s.retired_at IS NULL;\n snapshot:=entry.snapshot_digest;projection:=entry.projection_component;lunch:=entry.lunch_component;catalog:=entry.catalog_entry_digest;\n IF p_date<origin OR entry.template_id IS NULL\n  OR EXISTS(SELECT 1 FROM public.static_weekly_approved_template_retirements WHERE template_id=entry.template_id)\n  OR catalog IS DISTINCT FROM public.static_weekly_digest_jsonb(jsonb_build_object('template',entry.template_json,'binding',entry.binding_json,'ownerConfig',entry.owner_config,'approvalEvidence',entry.approval_evidence))\n  OR projection#>>'{authority,compilerInput,version,manualGroupRatingAuthority,manifestSha256}' IS DISTINCT FROM 'fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f'\n  OR NOT EXISTS(SELECT 1 FROM public.static_weekly_approved_initial_confirmations c WHERE c.publication_id=p_publication)\n THEN RAISE EXCEPTION 'Current live catalog and original accepted manual publication required'; END IF;\n frame:=public.static_weekly_source_window_start(projection#>'{authority,compilerInput}',p_date);\n IF frame IS DISTINCT FROM origin+((p_date-origin)/7)*7 THEN RAISE EXCEPTION 'Original publication origin differs from Source301 window authority'; END IF;\n IF frame<=origin THEN RAISE EXCEPTION 'Initial frame remains owned by the original activation'; END IF;\n IF public.static_weekly_effective_version(frame) IS DISTINCT FROM v_version_id\n  OR public.static_weekly_effective_version(frame+6) IS DISTINCT FROM v_version_id\n THEN RAISE EXCEPTION 'Period crosses or has left the original normal publication'; END IF;\n IF projection->>'database_projection_identity' IS DISTINCT FROM public.static_weekly_digest_jsonb(projection-'database_projection_identity')\n  OR lunch->>'document_identity' IS DISTINCT FROM public.static_weekly_digest_jsonb(lunch-'document_identity') THEN RAISE EXCEPTION 'Original admitted component identity differs'; END IF;\n IF jsonb_array_length(projection->'assignments') IS DISTINCT FROM (CASE projection#>>'{authority,compilerInput,version,lunchCoveragePolicy,sourceDigest}' WHEN 'eeff371f1510c6e4a079bde3ba17136dc10f64b100c7562d9b139fd14805a1c8' THEN 346 WHEN '85ad93db39597cffc033992ec74d5eea98612ce9a8388a9e93f5566f4e38bc4c' THEN 327 WHEN 'fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58' THEN 323 ELSE -1 END) OR jsonb_array_length(lunch->'loans') IS DISTINCT FROM (CASE projection#>>'{authority,compilerInput,version,lunchCoveragePolicy,sourceDigest}' WHEN 'eeff371f1510c6e4a079bde3ba17136dc10f64b100c7562d9b139fd14805a1c8' THEN 40 WHEN '85ad93db39597cffc033992ec74d5eea98612ce9a8388a9e93f5566f4e38bc4c' THEN 40 WHEN 'fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58' THEN 35 ELSE -1 END)\n  OR entry.owner_config->>'approvedManualDataDigest' IS DISTINCT FROM projection#>>'{authority,compilerInput,version,lunchCoveragePolicy,sourceDigest}'\n  OR projection#>>'{authority,overlayCompilerInput,version,lunchCoveragePolicy,sourceDigest}' IS DISTINCT FROM projection#>>'{authority,compilerInput,version,lunchCoveragePolicy,sourceDigest}'\n THEN RAISE EXCEPTION 'Original normal component counts differ'; END IF;\n exceptions:=public.static_weekly_accepted_exception_set(p_publication,frame);\n SELECT jsonb_agg(jsonb_build_object('serviceDate',service_day::date::text,\n  'assignmentEmployeeIds',(SELECT jsonb_agg(id ORDER BY id) FROM(SELECT DISTINCT item->>'owner_person_id' id FROM jsonb_array_elements(projection->'assignments') x(item) WHERE (item->>'day_of_week')::integer=extract(dow FROM service_day)::integer) ids),\n  'lunchOwnerEmployeeIds',(SELECT jsonb_agg(id ORDER BY id) FROM(SELECT DISTINCT item->>'normal_owner_person_id' id FROM jsonb_array_elements(lunch->'loans') x(item) WHERE (item->>'day_of_week')::integer=extract(dow FROM service_day)::integer) ids),\n  'lunchCovererEmployeeIds',(SELECT jsonb_agg(id ORDER BY id) FROM(SELECT DISTINCT item->>'coverer_person_id' id FROM jsonb_array_elements(lunch->'responsibilities') x(item) WHERE (item->>'day_of_week')::integer=extract(dow FROM service_day)::integer) ids)) ORDER BY service_day)\n INTO participants FROM generate_series(frame::timestamp,(frame+6)::timestamp,interval '1 day') dates(service_day);\n FOR d IN SELECT generate_series(frame::timestamp,(frame+6)::timestamp,interval '1 day')::date LOOP\n  FOR a IN SELECT value FROM jsonb_array_elements(projection#>'{authority,projectionAvailability}') WHERE value->>'status'='working' AND (value->>'dayOfWeek')::integer=extract(dow FROM d)::integer LOOP\n   IF NOT EXISTS(SELECT 1 FROM public.v_weekly_roster_slot_incumbency_ranges incumbency JOIN public.employees e ON e.id=incumbency.person_id\n    WHERE incumbency.slot_id=(a->>'slotId')::uuid AND incumbency.person_id=(a->>'incumbentPersonId')::uuid AND incumbency.effective_start<=d\n     AND (incumbency.effective_end IS NULL OR d<incumbency.effective_end) AND e.active)\n   THEN reasons:=reasons||jsonb_build_array(jsonb_build_object('kind','ACTUAL_ROSTER_CHANGED','serviceDate',d::text,'slotId',a->>'slotId')); END IF;\n  END LOOP;\n  readback:=custodial_employment.read_admissions(d,p_revision,p_manager,p_credential,p_device,p_access);\n  employment:=employment||jsonb_build_array(readback);\n END LOOP;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(lunch->'loans') l WHERE l->>'normal_owner_person_id'='1318b295-fd70-4e78-8828-62c29302f96f'\n  AND (l->>'coverage_start'<>'12:30' OR l->>'coverage_end'<>'13:30')) THEN\n  reasons:=reasons||jsonb_build_array(jsonb_build_object('kind','APPROVED_XAVIER_LUNCH_DIFFERS')); END IF;\n -- A bare same-frame projection does not prove current employment14 or a\n -- normal-reference admission. The typed recurring owner always obtains a real\n -- same-request repeat receipt; native writer replay still deduplicates bytes.\n existing:=NULL;\n RETURN jsonb_build_object('schema','custodial.approved-manual-recurring-basis.v1','managerId',p_manager,\n  'sourceId',v_source_id,'publicationId',p_publication,'versionId',v_version_id,'origin',origin::text,'frameStart',frame::text,'frameEnd',(frame+6)::text,\n  'authorityRevision',p_revision,'generation',public.static_weekly_v15_read_recurring_generation(),\n  'manifestSha256','fe02bbdebc736d95360b55cc7dfe5b73c5a9eaa76f364f1c0f4420a0afb9950f',\n  'baselineSnapshotDigest',snapshot,'catalogEntryDigest',catalog,'sourceProjectionIdentity',projection->>'database_projection_identity',\n  'sourceLunchIdentity',lunch->>'document_identity','manualDataDigest',projection#>>'{authority,compilerInput,version,lunchCoveragePolicy,sourceDigest}','assignmentCount',jsonb_array_length(projection->'assignments'),'lunchCount',jsonb_array_length(lunch->'loans'),'acceptedExceptions',exceptions,\n  'adjustmentReasons',reasons,'participants',participants,'employmentByDate',employment,'existingProjectionId',existing);\nEND $function$\n","owner":"postgres","acl":"{postgres=X/postgres,static_weekly_control_plane=X/postgres}","security":true,"config":["search_path=pg_catalog, public"],"recovery":[{"kind":"function","sha256":"61e67e2c6dc67355d1fd4744520b22634de4e7c8a8a4ec113589ed0dccfdfdc9","identity":"public.static_weekly_read_manual_repeat_basis(uuid,uuid,date,bigint,uuid,text,text)"},{"kind":"grant","sha256":"12a40d26cbf78c3d3f981263a0e7c8a96d123a8868b97d461b5b82630e7a6420","identity":"public.static_weekly_read_manual_repeat_basis(uuid,uuid,date,bigint,uuid,text,text)"}],"roots":[{"purpose":"exact approved manual shift policy and component count authority","object_kind":"function","object_identity":"public.static_weekly_read_manual_repeat_basis(uuid,uuid,date,bigint,uuid,text,text)"},{"purpose":"exact approved manual shift policy and component count authority","object_kind":"grant","object_identity":"public.static_weekly_read_manual_repeat_basis(uuid,uuid,date,bigint,uuid,text,text)"}],"new":false},{"identity":"public.static_weekly_list_coverall_activation_choices(uuid)","beforeSha256":"8072a10a762c4805533e0ed1c8bbe28b99353ee95eda7b52a7404524097d2c8e","afterSha256":"17a85f3aed81efcf9e1f0950efc3ec1e1448d08e02da6b31b9acd2e4be74ab0f","definition":"CREATE OR REPLACE FUNCTION public.static_weekly_list_coverall_activation_choices(p_manager uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE snapshot jsonb;day date;v_authority_revision bigint;choices jsonb;active jsonb;authority jsonb;\nBEGIN\n PERFORM public.static_weekly_v3_assert_control_plane();PERFORM public.static_weekly_v3_manager_actor(p_manager);\n PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));\n day:=public.sch_service_date(statement_timestamp());snapshot:=public.static_weekly_manual_roster_snapshot(day);v_authority_revision:=(snapshot->>'authorityRevision')::bigint;\n SELECT coalesce(jsonb_agg(jsonb_build_object('packetId',p.packet_id,'label',CASE WHEN p.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY' THEN 'Owner-approved seven-person schedule update; reuse existing positions' ELSE 'Owner-approved seven-day normal schedule with source-bound CoverAll capacity' END,\n  'serviceDate',p.service_date,'windowEnd',p.service_date+6,'expectedRevision',p.expected_revision,'activationEligible',true)||CASE WHEN p.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY' THEN jsonb_build_object('operationKind','ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY','manualDataDigest','fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58','acceptedArtifactSha256','22d067bd595e2450bb32cd36903df94628eb6df055a44f992b3aba9f242bbee7') ELSE '{}'::jsonb END ORDER BY p.packet_id),'[]') INTO choices\n FROM custodial_coverall.activation_packets p WHERE p.manager_id=p_manager AND p.service_date=day AND p.expected_revision=v_authority_revision\n  AND p.roster_digest=public.static_weekly_digest_jsonb(snapshot) AND (jsonb_array_length(snapshot->'rosterSlots')=22 AND p.approval_json->>'operationKind' IS DISTINCT FROM 'ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY' OR jsonb_array_length(snapshot->'rosterSlots')=30 AND p.approval_json->>'operationKind'='ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY' AND p.approval_json->>'artifactSha256'='22d067bd595e2450bb32cd36903df94628eb6df055a44f992b3aba9f242bbee7' AND p.source_json#>>'{version,lunchCoveragePolicy,sourceDigest}'='fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58')\n  AND NOT EXISTS(SELECT 1 FROM custodial_coverall.activation_operations o WHERE o.packet_id=p.packet_id);\n SELECT to_jsonb(a) INTO authority FROM public.static_weekly_v6_schedule_authority_state(day) a;\n SELECT jsonb_build_object('sourceId',v.authority_source_id,'publicationId',pub.publication_id,\n  'projectionId',CASE WHEN authority->>'publication_id'=pub.publication_id::text THEN authority->'projection_id' ELSE 'null'::jsonb END,\n  'authorityRevision',v_authority_revision,'projectionStatus',authority->>'projection_status','normalSourceLocked',true,\n  'initialOperationId',o.operation_id,'initialProjectionId',r.receipt_json->'projectionId') INTO active\n FROM custodial_coverall.activation_operations o JOIN custodial_coverall.activation_packets p USING(packet_id)\n JOIN custodial_coverall.activation_receipts r USING(operation_id)\n JOIN public.weekly_schedule_versions v ON v.authority_source_id=p.source_id\n JOIN public.weekly_schedule_publications pub USING(version_id)\n WHERE v.version_id=public.static_weekly_effective_version(day) AND r.receipt_json->>'schema'='custodial.approved-manual-coverall-source-confirmation.v2';\n RETURN jsonb_build_object('schema','custodial.approved-manual-activation-options.v2','serviceDate',day,'authorityRevision',v_authority_revision,'choices',choices,'active',active);\nEND $function$\n","owner":"postgres","acl":"{postgres=X/postgres,static_weekly_control_plane=X/postgres}","security":true,"config":["search_path=pg_catalog, public"],"recovery":[],"roots":[],"new":false},{"identity":"custodial_coverall.assert_accepted_seven_update_data(jsonb,jsonb)","definition":"-- Root candidate only. Install only in the complete qualified forward batch.\nCREATE FUNCTION custodial_coverall.assert_accepted_seven_update_data(p_data jsonb,p_snapshot jsonb)\nRETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public AS $accepted_update$\nDECLARE at date;person jsonb;position jsonb;predecessor jsonb;post jsonb;expected_vacancy jsonb;\n oldsource jsonb;source jsonb:=p_data->'source';capacity_ids jsonb;slot jsonb;oldslot jsonb;\n former constant text:='06228c5d-5123-4b8b-b730-e01114bdc971';\n former_slot constant text:='7044faec-4bbd-57ca-a898-ddd719503113';\n manual constant text:='fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58';\n artifact constant text:='22d067bd595e2450bb32cd36903df94628eb6df055a44f992b3aba9f242bbee7';\nBEGIN\n IF p_data IS NULL OR pg_column_size(p_data)>33554432\n  OR p_data->>'schema' IS DISTINCT FROM 'custodial.accepted-seven-pattern-update-data.v1'\n  OR p_data->>'manualDataDigest' IS DISTINCT FROM manual\n  OR p_data->>'acceptedArtifactSha256' IS DISTINCT FROM artifact\n  OR p_data#>>'{ownerConfig,approvedManualDataDigest}' IS DISTINCT FROM manual\n  OR p_data#>'{profile,staff}' IS DISTINCT FROM '7'::jsonb\n  OR p_data#>'{profile,assignments}' IS DISTINCT FROM '323'::jsonb\n  OR p_data#>'{profile,lunches}' IS DISTINCT FROM '35'::jsonb\n  OR p_data->'expectedRevision' IS DISTINCT FROM p_snapshot->'authorityRevision'\n  OR jsonb_array_length(p_snapshot->'rosterSlots') IS DISTINCT FROM 30\n  OR jsonb_array_length(p_snapshot->'employees') IS DISTINCT FROM 8\n  OR p_data->>'beforeRosterDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_snapshot)\n  OR p_data->>'updateDataDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(p_data-'updateDataDigest')\n  OR p_data->'newEmployees' IS DISTINCT FROM '0'::jsonb\n  OR p_data->'newCapacityPositions' IS DISTINCT FROM '0'::jsonb\n  OR p_data->'optimizerInvoked' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'registrationEligible' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'publicationEligible' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'registered' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'published' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'productionWritten' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'historyRewrite' IS DISTINCT FROM 'false'::jsonb\n  OR p_data->'weeklyBaselineChanged' IS DISTINCT FROM 'false'::jsonb\n  OR jsonb_typeof(source) IS DISTINCT FROM 'object'\n THEN RAISE EXCEPTION 'Exact accepted seven-person current update DATA required';END IF;\n at:=(p_snapshot->>'serviceDate')::date;\n PERFORM public.static_weekly_assert_exact_object(source,\n  ARRAY['exceptions','proximity','serviceDate','slots','version'],ARRAY['exceptions','proximity','serviceDate','slots','version'],'accepted seven compiler source');\n IF at IS DISTINCT FROM public.sch_service_date(statement_timestamp())\n  OR p_data->>'serviceDate' IS DISTINCT FROM at::text\n  OR p_data->>'windowEnd' IS DISTINCT FROM (at+6)::text\n  OR p_data->>'currentSourceId' IS DISTINCT FROM p_snapshot#>>'{parentPublication,sourceId}'\n  OR p_data->>'sourceDigest' IS DISTINCT FROM public.static_weekly_digest_jsonb(source)\n THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Accepted update service date, parent or source changed';END IF;\n SELECT canonical_source INTO STRICT oldsource FROM public.static_weekly_authority_source_documents\n  WHERE source_id=(p_data->>'currentSourceId')::uuid AND active AND retired_at IS NULL\n   AND source_digest=p_data->>'currentSourceDigest'\n   AND source_digest=public.static_weekly_digest_jsonb(canonical_source) FOR SHARE;\n IF public.static_weekly_digest_jsonb((source->'version')-ARRAY['id','publicationId','status','effectiveStart','vacantSlotIds'])\n   IS DISTINCT FROM '05af8d0eec2f9fb7bf1f0219b2d322ca9a974699158641a1bbb6f4fa9a858b28'\n  OR public.static_weekly_digest_jsonb((p_data->'ownerConfig')-'effectiveDate')\n   IS DISTINCT FROM '1ff96fd571c463a8e46591d6ad71e2297270fcede9a5f3897d2ea57daf30e756'\n  OR p_data#>>'{ownerConfig,effectiveDate}' IS DISTINCT FROM at::text\n  OR source->'proximity' IS DISTINCT FROM oldsource->'proximity'\n  OR p_data#>'{template,roleSlotIds}' IS DISTINCT FROM '[\"36829381-70d7-521b-9f14-bad0af16ba87\",\"4a5a83ca-d297-5a30-8344-db08d05b978c\",\"55e5939c-175c-5026-94fd-c4350d538922\",\"5d2d2a0e-230f-5b03-9867-2e4c2826871f\",\"ae56a131-e2fd-5465-8ab8-6e5dbf543204\",\"e91b7a47-f20f-5777-a5d3-9c0ce8778df5\",\"f22348e9-d4b9-5a7e-b8fd-d0d2c1ec534f\"]'::jsonb\n THEN RAISE EXCEPTION 'Exact accepted static normal geometry, roles, owner restrictions and unchanged travel facts required';END IF;\n SELECT value INTO STRICT person FROM jsonb_array_elements(p_snapshot->'employees') WHERE value->>'employeeId'=former;\n SELECT value INTO STRICT position FROM jsonb_array_elements(p_snapshot->'rosterSlots') WHERE value->>'slotId'=former_slot;\n IF person->>'displayName' IS DISTINCT FROM 'Kiltra Horton' OR person->'active' IS DISTINCT FROM 'true'::jsonb\n  OR person->'hasMessenger' IS DISTINCT FROM 'true'::jsonb OR coalesce(person->>'employeeCode','')!~'^EMP[0-9]+$'\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(position->'incumbencies') row WHERE (row->>'effectiveStart')::date>=at)\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_snapshot->'rosterSlots') other\n   CROSS JOIN LATERAL jsonb_array_elements(other->'incumbencies') row WHERE other->>'slotId'<>former_slot\n    AND row->>'personId'=former AND (row->>'effectiveEnd' IS NULL OR (row->>'effectiveEnd')::date>at))\n THEN RAISE EXCEPTION 'Exact protected predecessor, active Messenger and stable position required';END IF;\n SELECT row INTO STRICT predecessor FROM jsonb_array_elements(position->'incumbencies') row\n  WHERE (row->>'effectiveStart')::date<at AND (row->>'effectiveEnd' IS NULL OR at<(row->>'effectiveEnd')::date);\n IF predecessor->>'personId' IS DISTINCT FROM former OR predecessor->>'displayName' IS DISTINCT FROM person->>'displayName'\n THEN RAISE EXCEPTION 'Accepted update cannot replace a different incumbent';END IF;\n post:=jsonb_set(p_snapshot,'{authorityRevision}',to_jsonb((p_snapshot->>'authorityRevision')::bigint+1),false);\n SELECT jsonb_set(post,'{employees}',jsonb_agg(CASE WHEN row->>'employeeId'=former\n  THEN row||jsonb_build_object('active',false,'hasMessenger',false) ELSE row END ORDER BY n),false)\n INTO post FROM jsonb_array_elements(p_snapshot->'employees') WITH ORDINALITY x(row,n);\n SELECT jsonb_set(post,'{rosterSlots}',jsonb_agg(CASE WHEN row->>'slotId'=former_slot\n  THEN jsonb_set(row,'{incumbencies}',(SELECT jsonb_agg(CASE WHEN incumbent->'incumbencyId'=predecessor->'incumbencyId'\n   THEN incumbent||jsonb_build_object('effectiveEnd',at::text) ELSE incumbent END ORDER BY ordinal)\n   FROM jsonb_array_elements(row->'incumbencies') WITH ORDINALITY ranges(incumbent,ordinal)),false)\n  ELSE row END ORDER BY n),false)\n INTO post FROM jsonb_array_elements(p_snapshot->'rosterSlots') WITH ORDINALITY x(row,n);\n expected_vacancy:=jsonb_build_object('schema','custodial.accepted-seven-supported-vacancy-model.v1',\n  'beforeRosterDigest',public.static_weekly_digest_jsonb(p_snapshot),'expectedPostRosterDigest',public.static_weekly_digest_jsonb(post),\n  'expectedPostSnapshot',post,'employeeId',former,'slotId',former_slot,'predecessorIncumbencyId',predecessor->'incumbencyId',\n  'effectiveDate',at::text,'expectedRevision',p_snapshot->'authorityRevision','expectedPostRevision',post->'authorityRevision',\n  'actualSqlExecuted',false,'liveVacancyObserved',false);\n IF p_data->'vacancy' IS DISTINCT FROM expected_vacancy\n  OR p_data#>'{approvalEvidence,vacancy}' IS DISTINCT FROM expected_vacancy\n  OR p_data#>>'{approvalEvidence,operationKind}' IS DISTINCT FROM 'ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY'\n  OR p_data#>>'{approvalEvidence,artifactSha256}' IS DISTINCT FROM artifact\n  OR p_data#>>'{approvalEvidence,classification}' IS DISTINCT FROM 'OWNER_APPROVED_OPERATIONAL_PATTERN'\n  OR nullif(p_data#>>'{approvalEvidence,sourceReference}','') IS NULL\n  OR nullif(p_data#>>'{approvalEvidence,ownerDecisionReference}','') IS NULL\n THEN RAISE EXCEPTION 'Exact modeled supported vacancy and accepted owner evidence required';END IF;\n PERFORM public.static_weekly_assert_manual_roster_transition(p_data->'transition',post,p_data->'ownerConfig');\n IF jsonb_array_length(p_data#>'{transition,transfers}') IS DISTINCT FROM 0\n  OR jsonb_array_length(p_data#>'{transition,unchanged}') IS DISTINCT FROM 7\n  OR source->>'serviceDate' IS DISTINCT FROM at::text OR source#>>'{version,effectiveStart}' IS DISTINCT FROM at::text\n  OR source->'exceptions' IS DISTINCT FROM '[]'::jsonb\n  OR source#>>'{version,lunchCoveragePolicy,sourceDigest}' IS DISTINCT FROM manual\n  OR source#>>'{version,manualGroupRatingAuthority,acceptedCandidateSha256}' IS DISTINCT FROM artifact\n  OR source#>>'{version,manualGroupRatingAuthority,acceptedManualDataDigest}' IS DISTINCT FROM manual\n  OR jsonb_array_length(source#>'{version,assignments}') IS DISTINCT FROM 323\n  OR jsonb_array_length(source#>'{version,slotAvailability}') IS DISTINCT FROM 35\n  OR jsonb_array_length(source#>'{version,lunchCoveragePolicy,loans}') IS DISTINCT FROM 35\n  OR jsonb_array_length(source->'slots') IS DISTINCT FROM 17\n  OR source#>'{version,vacantSlotIds}' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(row->'id' ORDER BY row->>'id'),'[]'::jsonb)\n   FROM jsonb_array_elements(source->'slots') row WHERE row->>'kind' IS DISTINCT FROM 'CONTRACTOR_CAPACITY' AND row->'incumbencies'='[]'::jsonb)\n  OR p_data#>'{template,staffingCount}' IS DISTINCT FROM '7'::jsonb\n  OR p_data#>'{template,source}' IS DISTINCT FROM source\n  OR p_data#>'{feasibility,candidateSource}' IS DISTINCT FROM source\n  OR p_data#>'{feasibility,solverInvoked}' IS DISTINCT FROM 'false'::jsonb\n  OR p_data#>'{feasibility,mapping,unchanged}' IS DISTINCT FROM 'true'::jsonb\n  OR jsonb_array_length(p_data#>'{feasibility,initialBaseline,projection,assignments}') IS DISTINCT FROM 323\n  OR jsonb_array_length(p_data#>'{feasibility,lunchDocument,loans}') IS DISTINCT FROM 35\n THEN RAISE EXCEPTION 'Exact accepted normal geometry and existing fixed-pattern proof required';END IF;\n SELECT jsonb_agg(row->'id' ORDER BY row->>'id') INTO capacity_ids\n FROM jsonb_array_elements(oldsource->'slots') row WHERE row->>'kind'='CONTRACTOR_CAPACITY';\n IF jsonb_array_length(capacity_ids) IS DISTINCT FROM 8 OR p_data->'capacityTransition' IS DISTINCT FROM jsonb_build_object(\n  'schema','custodial.reuse-existing-native-capacity.v1','newCapacityIds','[]'::jsonb,'reusedCapacityIds',capacity_ids,\n  'newPositionsCreated',0,'expectedRosterPositions',jsonb_array_length(p_snapshot->'rosterSlots'))\n THEN RAISE EXCEPTION 'Reuse exact existing eight native capacity positions; enrollment is not permitted';END IF;\n FOR slot IN SELECT value FROM jsonb_array_elements(source->'slots') LOOP\n  SELECT value INTO STRICT oldslot FROM jsonb_array_elements(oldsource->'slots') WHERE value->'id'=slot->'id';\n  IF slot->>'kind'='CONTRACTOR_CAPACITY' THEN\n   PERFORM public.static_weekly_capacity_assert_shape(slot);\n   IF slot IS DISTINCT FROM oldslot OR NOT EXISTS(SELECT 1 FROM public.static_weekly_contractor_capacity_registrations registration\n    WHERE registration.capacity_slot_id::text=slot->>'id' AND registration.slot_snapshot=slot\n     AND registration.slot_digest=public.static_weekly_digest_jsonb(slot))\n    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(post->'rosterSlots') row\n     WHERE row->'slotId'=slot->'id' AND row->'incumbencies'='[]'::jsonb)\n   THEN RAISE EXCEPTION 'Registered native nonemployee capacity/history changed';END IF;\n  ELSE\n   IF slot-'incumbencies' IS DISTINCT FROM oldslot-'incumbencies' THEN RAISE EXCEPTION 'Ordinary stable position metadata changed';END IF;\n   SELECT jsonb_agg(jsonb_build_object('personId',incumbent->'personId','displayName',incumbent->'displayName',\n    'effectiveStart',incumbent->'effectiveStart','effectiveEnd',incumbent->'effectiveEnd') ORDER BY n) INTO oldslot\n   FROM jsonb_array_elements(post->'rosterSlots') row CROSS JOIN LATERAL jsonb_array_elements(row->'incumbencies') WITH ORDINALITY ranges(incumbent,n)\n   WHERE row->'slotId'=slot->'id' AND (incumbent->>'effectiveStart')::date<=at+6\n    AND (incumbent->>'effectiveEnd' IS NULL OR (incumbent->>'effectiveEnd')::date>at);\n   IF slot->'incumbencies' IS DISTINCT FROM coalesce(oldslot,'[]'::jsonb) THEN RAISE EXCEPTION 'Projected ordinary history changed beyond the supported closure';END IF;\n  END IF;\n END LOOP;\nEND $accepted_update$;\nREVOKE ALL ON FUNCTION custodial_coverall.assert_accepted_seven_update_data(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role,static_weekly_control_plane,static_weekly_release_operator,custodial_application_reader;\n","new":true},{"identity":"custodial_coverall.begin_accepted_seven_update(uuid,uuid,uuid,bigint,text,uuid,text,text)","definition":"-- Root candidate only. No production installation/admission yet.\nCREATE FUNCTION custodial_coverall.begin_accepted_seven_update(p_manager uuid,p_packet uuid,p_operation uuid,p_revision bigint,\n p_preview text,p_credential uuid,p_device text,p_access text)\nRETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public AS $accepted_update$\nDECLARE packet record;before_snapshot jsonb;post_snapshot jsonb;basis jsonb;result jsonb;vacancy jsonb;\n request jsonb;prior record;employees_before text;messenger_before text;devices_before text;catalog_before text;\n former constant uuid:='06228c5d-5123-4b8b-b730-e01114bdc971';\n former_slot constant uuid:='7044faec-4bbd-57ca-a898-ddd719503113';\nBEGIN\n PERFORM public.static_weekly_v3_assert_control_plane();\n PERFORM public.custodial_action_actor_v1(p_manager,p_credential,p_device,p_access,'write');\n PERFORM public.custodial_begin_application_mutation();\n PERFORM pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));\n request:=jsonb_build_object('managerId',p_manager,'packetId',p_packet,'operationId',p_operation,'expectedRevision',p_revision,'previewDigest',p_preview);\n SELECT operation.request_json,receipt.receipt_json INTO prior FROM custodial_coverall.activation_operations operation\n  JOIN custodial_coverall.activation_receipts receipt USING(operation_id) WHERE operation.operation_id=p_operation;\n IF FOUND THEN\n  IF prior.request_json IS DISTINCT FROM request THEN RAISE EXCEPTION 'Original accepted-update identity conflict';END IF;\n  RETURN prior.receipt_json;\n END IF;\n SELECT packet_id,source_id,template_id,manager_id,service_date,expected_revision,roster_digest,\n  source_json,source_digest,transition_json,capacity_json,owner_config,template_json,binding_json,approval_json,packet_fingerprint\n INTO STRICT packet FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;\n before_snapshot:=public.static_weekly_manual_roster_snapshot(public.sch_service_date(statement_timestamp()));\n IF p_operation IS NULL OR packet.manager_id IS DISTINCT FROM p_manager OR packet.expected_revision IS DISTINCT FROM p_revision\n  OR packet.service_date::text IS DISTINCT FROM before_snapshot->>'serviceDate'\n  OR p_revision::text IS DISTINCT FROM before_snapshot->>'authorityRevision'\n  OR packet.roster_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(before_snapshot)\n  OR p_preview IS DISTINCT FROM (public.static_weekly_read_coverall_activation_basis(p_manager,p_packet,p_revision)->>'previewDigest')\n  OR packet.approval_json->>'operationKind' IS DISTINCT FROM 'ACCEPTED_SEVEN_UPDATE_REUSE_EXISTING_CAPACITY'\n  OR packet.approval_json->>'artifactSha256' IS DISTINCT FROM '22d067bd595e2450bb32cd36903df94628eb6df055a44f992b3aba9f242bbee7'\n  OR packet.approval_json#>>'{vacancy,employeeId}' IS DISTINCT FROM former::text\n  OR packet.approval_json#>>'{vacancy,slotId}' IS DISTINCT FROM former_slot::text\n  OR packet.source_digest IS DISTINCT FROM public.static_weekly_digest_jsonb(packet.source_json)\n  OR packet.source_json#>>'{version,lunchCoveragePolicy,sourceDigest}' IS DISTINCT FROM 'fe0257dbd8cb4dd2f63c4da1997342067945e87a6ce516aee0698debef5d9a58'\n THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='Exact current accepted-update packet, actor or readback changed';END IF;\n SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.id)) INTO employees_before\n  FROM public.employees row WHERE row.id<>former;\n SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.id)) INTO messenger_before\n  FROM public.msg_users row WHERE row.employee_id IS DISTINCT FROM former;\n SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.id)) INTO devices_before FROM public.devices row;\n SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.template_id)) INTO catalog_before\n  FROM public.static_weekly_approved_template_catalog row WHERE row.template_id<>packet.template_id;\n INSERT INTO custodial_coverall.activation_operations VALUES(p_operation,p_packet,p_manager,pg_current_xact_id(),request);\n -- The private operation/current transaction is the only context permitting\n -- v8's mutation-only subreceipt; the outer original operation owns publication.\n vacancy:=public.static_weekly_v8_vacate_roster_slot(\n  (before_snapshot#>>'{parentPublication,sourceId}')::uuid,former_slot,former,packet.service_date,\n  'Accepted seven-person owner-approved pattern; preserve former employee work and history.',\n  p_revision,p_manager,'accepted-seven-vacancy:'||p_operation);\n post_snapshot:=public.static_weekly_manual_roster_snapshot(packet.service_date);\n IF vacancy->>'revision' IS DISTINCT FROM (p_revision+1)::text\n  OR vacancy#>>'{data,completion_mode}' IS DISTINCT FROM 'mutation_only'\n  OR vacancy#>'{data,original_publication_id}' IS DISTINCT FROM 'null'::jsonb\n  OR vacancy#>'{data,history_preserved}' IS DISTINCT FROM 'true'::jsonb\n  OR post_snapshot IS DISTINCT FROM packet.approval_json#>'{vacancy,expectedPostSnapshot}'\n  OR public.static_weekly_digest_jsonb(post_snapshot) IS DISTINCT FROM packet.approval_json#>>'{vacancy,expectedPostRosterDigest}'\n THEN RAISE EXCEPTION 'Actual supported protected vacancy differs from the exact prepared model';END IF;\n INSERT INTO public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)\n  VALUES(packet.source_id,packet.source_json,packet.source_digest,'approved-manual-coverall:'||p_operation);\n -- Source and typed slots were checked against the existing immutable native\n -- registrations at preparation. No roster/capacity enrollment occurs here.\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(packet.source_json->'slots') slot WHERE slot->>'kind'='CONTRACTOR_CAPACITY'\n  AND NOT EXISTS(SELECT 1 FROM public.static_weekly_contractor_capacity_registrations registration\n   WHERE registration.capacity_slot_id::text=slot->>'id' AND registration.slot_snapshot=slot\n    AND registration.slot_digest=public.static_weekly_digest_jsonb(slot)))\n THEN RAISE EXCEPTION 'Existing registered capacity changed before accepted update';END IF;\n PERFORM public.static_weekly_v3_source_identity(packet.source_json);\n PERFORM public.static_weekly_coverall_register_template(packet.source_id,packet.template_json,packet.binding_json,packet.owner_config,packet.approval_json);\n INSERT INTO public.static_weekly_manual_activation_packets(packet_id,source_id,template_id,service_date,manager_id,transition_json,feasibility_json,packet_digest)\n  SELECT packet_id,source_id,template_id,service_date,manager_id,transition_json,feasibility_json,packet_fingerprint\n  FROM custodial_coverall.activation_packets WHERE packet_id=p_packet;\n basis:=public.static_weekly_coverall_activation_basis(p_manager,p_packet,p_revision+1);\n result:=public.static_weekly_coverall_activate_source301(p_manager,p_packet,p_revision+1,basis->>'previewDigest','coverall-source:'||p_operation);\n IF result->>'status' IS DISTINCT FROM 'PERSISTED_CURRENT' OR result->>'source_id' IS DISTINCT FROM packet.source_id::text\n  OR (SELECT count(*) FROM public.weekly_roster_slots) IS DISTINCT FROM jsonb_array_length(before_snapshot->'rosterSlots')::bigint\n  OR employees_before IS DISTINCT FROM (SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.id)) FROM public.employees row WHERE row.id<>former)\n  OR messenger_before IS DISTINCT FROM (SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.id)) FROM public.msg_users row WHERE row.employee_id IS DISTINCT FROM former)\n  OR devices_before IS DISTINCT FROM (SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.id)) FROM public.devices row)\n  OR catalog_before IS DISTINCT FROM (SELECT public.static_weekly_digest_jsonb(jsonb_agg(to_jsonb(row) ORDER BY row.template_id)) FROM public.static_weekly_approved_template_catalog row WHERE row.template_id<>packet.template_id)\n  OR EXISTS(SELECT 1 FROM public.weekly_roster_slot_incumbencies WHERE slot_id::text IN(SELECT jsonb_array_elements_text(packet.capacity_json->'reusedCapacityIds')))\n THEN RAISE EXCEPTION 'Accepted update did not preserve people, devices, eight-person catalog and native capacity';END IF;\n result:=result||jsonb_build_object('acceptedPatternUpdate',jsonb_build_object('schema','custodial.accepted-seven-update-result.v1',\n  'operationId',p_operation,'packetId',p_packet,'vacancySubreceipt',vacancy,'vacancyIdempotencyKey','accepted-seven-vacancy:'||p_operation,\n  'reusedCapacityPositions',8,'newCapacityPositions',0,'historyPreserved',true));\n RETURN public.static_weekly_coverall_record_activation_begin(p_operation,p_manager,p_credential,p_device,p_access,result);\nEND $accepted_update$;\nREVOKE ALL ON FUNCTION custodial_coverall.begin_accepted_seven_update(uuid,uuid,uuid,bigint,text,uuid,text,text) FROM PUBLIC,anon,authenticated,service_role,static_weekly_control_plane,static_weekly_release_operator,custodial_application_reader;\n","new":true},{"identity":"public.custodial_release_canary_authority_surface()","beforeSha256":"bb16474f41949f5808f93784d9b758477433ddcf08ba80b9171bc4a63d26e846","afterSha256":"36efc5853ac0e6d57bf5c058cedbcf0e78ee9ca835512eccebff0d261ce99470","definition":"CREATE OR REPLACE FUNCTION public.custodial_release_canary_authority_surface()\n RETURNS TABLE(object_kind text, object_identity text, purpose text)\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\n  values\n    ('function','public.static_weekly_manual_assert_native_lunch(uuid,jsonb,jsonb,uuid,date)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('grant','public.static_weekly_manual_assert_native_lunch(uuid,jsonb,jsonb,uuid,date)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('function','public.static_weekly_v8_vacate_roster_slot(uuid,uuid,uuid,date,text,bigint,uuid,text)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('grant','public.static_weekly_v8_vacate_roster_slot(uuid,uuid,uuid,date,text,bigint,uuid,text)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('function','public.static_weekly_begin_coverall_activation(uuid,uuid,uuid,bigint,text,uuid,text,text)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('grant','public.static_weekly_begin_coverall_activation(uuid,uuid,uuid,bigint,text,uuid,text,text)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('function','public.static_weekly_coverall_activation_filtered_roster(uuid)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('grant','public.static_weekly_coverall_activation_filtered_roster(uuid)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('function','public.static_weekly_read_coverall_activation_basis(uuid,uuid,bigint)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('grant','public.static_weekly_read_coverall_activation_basis(uuid,uuid,bigint)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('function','public.static_weekly_list_coverall_activation_choices(uuid)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('grant','public.static_weekly_list_coverall_activation_choices(uuid)','exact accepted seven-person update authority; retained permissions and recovery'),\n    ('function','custodial_coverall.assert_accepted_seven_update_data(jsonb,jsonb)','private exact accepted seven-person compound authority; owner-only execution'),\n    ('grant','custodial_coverall.assert_accepted_seven_update_data(jsonb,jsonb)','private exact accepted seven-person compound authority; owner-only execution'),\n    ('function','custodial_coverall.begin_accepted_seven_update(uuid,uuid,uuid,bigint,text,uuid,text,text)','private exact accepted seven-person compound authority; owner-only exec